export type LauncherSpot = { edge: "bottom" | "right"; t: number } | { edge: "free"; x: number; y: number };
export type EdgeSpot = { edge: "bottom" | "right"; t: number };
export type LauncherBounds = { width: number; height: number; top: number; left?: number };
export type PanelSize = { width: number; height: number };
export type PanelEdge = "left" | "top" | "corner";
export const LAUNCHER_SIZE: 44;
export const DEFAULT_LAUNCHER_SPOT: EdgeSpot;
export const PANEL_DEFAULT: PanelSize;
export const PANEL_MIN: PanelSize;
export const PANEL_MARGIN: 20;
export const PANEL_PHONE_MAX: 640;
export const PANEL_EDGES: readonly PanelEdge[];
export function normalizeSpot(value: unknown): EdgeSpot;
export function launcherPosition(spot: LauncherSpot, bounds: LauncherBounds): {x: number; y: number};
export function snapLauncher(point: {x: number; y: number}, bounds: LauncherBounds): EdgeSpot;
export function panelBounds(viewport: PanelSize): { min: PanelSize; max: PanelSize };
export function clampPanelSize(size: PanelSize, viewport: PanelSize): PanelSize;
export function defaultPanelSize(viewport: PanelSize): PanelSize;
export function readPanelSize(value: unknown): PanelSize | null;
export function draggedPanelSize(start: PanelSize, edge: PanelEdge, dx: number, dy: number, viewport: PanelSize): PanelSize;
